css:
body :where([data-bz-node="hi"]) .bz-block{padding:0}
body :where([data-bz-node="hi"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="hi"]>.bz-container{padding-inline:0}

body [data-bz-node="hi"]{position:relative;overflow:hidden;background:#2b2824;padding:80px 0;min-height:520px;display:flex;flex-direction:column;justify-content:center}
body [data-bz-node="hi"]>.bz-container{max-width:var(--container)}
body [data-bz-node="hi-img"]{position:absolute;inset:0;z-index:0}
body [data-bz-node="hi-img"] figure{margin:0;height:100%}
body [data-bz-node="hi-img"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 50%;border-radius:0}
body [data-bz-node="hi-row"]{display:flex;justify-content:flex-end;position:relative;z-index:2}
body [data-bz-node="hi-card"]{grid-column:auto;width:100%;max-width:600px;background:rgba(255,255,255,.96);border:1px solid #fff;padding:40px 40px 42px;box-sizing:border-box}
body [data-bz-node="hi-h"] h2{font:700 30px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 22px}
body [data-bz-node="hi-text"] .bz-text{max-width:none}
body [data-bz-node="hi-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="hi-cta"]{margin-top:22px}
body [data-bz-node="hi-cta"] .bz-btns{margin:0}
body [data-bz-node="hi-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node="hi-cta"] .bz-btn:hover{background:var(--accent-dark)}
@media (max-width:1100px){body [data-bz-node="hi"]{padding:56px 24px}}
@media (max-width:820px){body [data-bz-node="hi-row"]{justify-content:center}}
@media (max-width:640px){body [data-bz-node="hi"]{padding:40px 20px;min-height:0}body [data-bz-node="hi-card"]{padding:26px 22px}body [data-bz-node="hi-h"] h2{font-size:24px}}
